controls.arguments:
(Button {
            label: "CALIBRATE IN HEADSET".into(),
            caption: "START".into(),
            action: start,
        })

(Button {
            label: "MEASURE SEATED EYES".into(),
            caption: "MEASURE".into(),
            action: || measure(live_eye_height()),
        })

(Button {
            label: "MEASURE ARM SPAN".into(),
            caption: "MEASURE".into(),
            action: || measure(live_grip_span()),
        })

(Readout {
            label: "ARM SPAN, ESTIMATED".into(),
            read: || live_estimate(|c, grip| c.arm_span_for(grip)),
        })

(Readout {
            label: "HEIGHT, ESTIMATED".into(),
            read: || live_estimate(|c, grip| c.height_for_span(grip)),
        })

(Button {
            label: "MEASURE STEP 1 AGAIN".into(),
            caption: "BACK".into(),
            action: back,
        })

(Slider {
            label: "HEIGHT".into(),
            range: HEIGHT_RANGE,
            format: SliderFormat::new(2, " M"),
            get: || CALIBRATION.lock().height().unwrap_or(f32::NAN),
            set: |height| {
                CALIBRATION.lock().set_height(height);
            },
            default: estimate.map_or(HEIGHT_RANGE.min, |height| {
                height.clamp(HEIGHT_RANGE.min, HEIGHT_RANGE.max)
            }),
        })

(Button {
            label: "ARM SPAN ONLY".into(),
            caption: "BACK".into(),
            action: back,
        })

(Button {
            label: "KEEP MY SETTINGS".into(),
            caption: "CANCEL".into(),
            action: || {
                CONFIRMING_RESET.store(false, Ordering::Relaxed);
                ButtonOutcome::Rebuild
            },
        })

(Button {
            label: "RESET CONTROLS AND COMFORT".into(),
            caption: "RESET".into(),
            action: || {
                reset_shown_settings();
                CONFIRMING_RESET.store(false, Ordering::Relaxed);
                ButtonOutcome::Rebuild
            },
        })

(Button {
            label: "RESET TO DEFAULTS".into(),
            caption: "RESET".into(),
            action: || {
                CONFIRMING_RESET.store(true, Ordering::Relaxed);
                ButtonOutcome::Rebuild
            },
        })

(Choice {
            label: SNAP_TURN_ANGLE.into(),
            options: &SNAP_ANGLE_LABELS,
            get: || {
                nearest_index(
                    &SNAP_ANGLES,
                    read_config(|c| c.headpose.vr_turn.snap_angle_deg),
                )
            },
            set: |index| {
                if let Some(&angle) = SNAP_ANGLES.get(index) {
                    edit_config(|c| c.headpose.vr_turn.snap_angle_deg = angle);
                }
            },
            default: nearest_index(&SNAP_ANGLES, VrTurnConfig::new().snap_angle_deg),
        })
